    "inlineSchema": "generator client {\n  provider = \"prisma-client\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum UserRole {\n  STUDENT\n  FACULTY\n  ADMIN\n}\n\nenum ServiceRequestStatus {\n  RECEIVED\n  PROCESSING\n  WAITING_FOR_APPROVAL\n  APPROVED\n  REJECTED\n  COMPLETED\n  FAILED\n}\n\nenum ApprovalStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  MORE_INFO_REQUIRED\n}\n\nenum BookingStatus {\n  CONFIRMED\n  CANCELLED\n}\n\nenum ResourceType {\n  LAB\n  CLASSROOM\n  SEMINAR_HALL\n  EQUIPMENT\n  OTHER\n}\n\nenum AuditEventType {\n  REQUEST_RECEIVED\n  AI_REASONING_STARTED\n  AI_REASONING_COMPLETED\n  POLICY_RETRIEVED\n  POLICY_CONFLICT_DETECTED\n  ACTION_PROPOSED\n  APPROVAL_REQUESTED\n  APPROVAL_GRANTED\n  APPROVAL_REJECTED\n  MORE_INFORMATION_REQUESTED\n  ACTION_EXECUTED\n  BOOKING_CREATED\n  REQUEST_COMPLETED\n  REQUEST_FAILED\n}\n\nmodel Institution {\n  id        String   @id @default(uuid())\n  name      String\n  code      String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  departments     Department[]\n  users           User[]\n  resources       Resource[]\n  serviceRequests ServiceRequest[]\n  bookings        Booking[]\n  approvals       Approval[]\n  auditEvents     AuditEvent[]\n}\n\nmodel Department {\n  id            String @id @default(uuid())\n  institutionId String\n  name          String\n  code          String\n\n  institution Institution @relation(fields: [institutionId], references: [id])\n  users       User[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([institutionId, code])\n  @@index([institutionId])\n}\n\nmodel User {\n  id            String  @id @default(uuid())\n  institutionId String\n  departmentId  String?\n\n  name  String\n  email String\n  role  UserRole\n\n  institution Institution @relation(fields: [institutionId], references: [id])\n  department  Department? @relation(fields: [departmentId], references: [id])\n\n  serviceRequests ServiceRequest[]\n  bookings        Booking[]\n  approvals       Approval[]\n  auditEvents     AuditEvent[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([institutionId, email])\n  @@index([institutionId])\n  @@index([departmentId])\n}\n\nmodel Resource {\n  id            String @id @default(uuid())\n  institutionId String\n\n  name     String\n  type     ResourceType\n  location String?\n  capacity Int?\n\n  institution Institution @relation(fields: [institutionId], references: [id])\n  bookings    Booking[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([institutionId, name])\n  @@index([institutionId])\n}\n\nmodel ServiceRequest {\n  id            String @id @default(uuid())\n  institutionId String\n  userId        String\n\n  message String\n  intent  String?\n  status  ServiceRequestStatus @default(RECEIVED)\n\n  institution Institution @relation(fields: [institutionId], references: [id])\n  user        User        @relation(fields: [userId], references: [id])\n\n  booking     Booking?\n  approval    Approval?\n  auditEvents AuditEvent[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([institutionId])\n  @@index([userId])\n  @@index([status])\n}\n\nmodel Booking {\n  id            String @id @default(uuid())\n  institutionId String\n  resourceId    String\n  userId        String\n  requestId     String @unique\n\n  date      DateTime\n  startTime DateTime\n  endTime   DateTime\n  purpose   String?\n  status    BookingStatus @default(CONFIRMED)\n\n  institution Institution    @relation(fields: [institutionId], references: [id])\n  resource    Resource       @relation(fields: [resourceId], references: [id])\n  user        User           @relation(fields: [userId], references: [id])\n  request     ServiceRequest @relation(fields: [requestId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([institutionId])\n  @@index([resourceId, date])\n  @@index([userId])\n}\n\nmodel Approval {\n  id            String  @id @default(uuid())\n  institutionId String\n  requestId     String  @unique\n  approverId    String?\n\n  status     ApprovalStatus @default(PENDING)\n  reason     String?\n  resolvedAt DateTime?\n\n  institution Institution    @relation(fields: [institutionId], references: [id])\n  request     ServiceRequest @relation(fields: [requestId], references: [id])\n  approver    User?          @relation(fields: [approverId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([institutionId])\n  @@index([status])\n  @@index([approverId])\n}\n\nmodel AuditEvent {\n  id            String  @id @default(uuid())\n  institutionId String\n  requestId     String\n  actorId       String?\n\n  eventType AuditEventType\n  metadata  Json?\n\n  institution Institution    @relation(fields: [institutionId], references: [id])\n  request     ServiceRequest @relation(fields: [requestId], references: [id])\n  actor       User?          @relation(fields: [actorId], references: [id])\n\n  createdAt DateTime @default(now())\n\n  @@index([institutionId])\n  @@index([requestId, createdAt])\n  @@index([actorId])\n}\n",
